            ['jupiter_big', [6, 8], '🟠', ['The biggest planet', 'سب سے بڑا سیارہ'], ['Jupiter is the biggest planet. More than 1,000 Earths could fit inside it.', 'مشتری سب سے بڑا سیارہ ہے۔ اس میں 1,000 سے زیادہ زمینیں سما سکتی ہیں۔'], ['Which is the biggest planet?', 'سب سے بڑا سیارہ کون سا ہے؟'], ['Jupiter', 'مشتری'], [['Earth', 'زمین'], ['Mars', 'مریخ']]],
            ['day_night', [6, 8], '🌍', ['Day and night', 'دن اور رات'], ['The Earth slowly spins like a top. When our side faces the Sun it is day. When it turns away from the Sun it is night.', 'زمین لٹو کی طرح آہستہ آہستہ گھومتی ہے۔ جب ہماری طرف سورج کے سامنے ہوتی ہے تو دن ہوتا ہے۔ جب وہ سورج سے دور ہو جاتی ہے تو رات ہوتی ہے۔'], ['Why do we have night?', 'رات کیوں ہوتی ہے؟'], ['Our side of the Earth turns away from the Sun', 'زمین کا ہماری طرف کا حصہ سورج سے دور ہو جاتا ہے'], [['The Sun goes out', 'سورج بجھ جاتا ہے'], ['A cloud covers the Sun', 'بادل سورج کو ڈھانپ لیتا ہے']]],
            ['galaxy', [9, 10], '🌌', ['Galaxies', 'کہکشائیں'], ['A galaxy is a huge family of stars, gas and dust held together by gravity. Our galaxy is called the Milky Way and it has hundreds of billions of stars.', 'کہکشاں ستاروں، گیس اور گرد کا ایک بہت بڑا خاندان ہے جو کششِ ثقل سے جڑا ہوتا ہے۔ ہماری کہکشاں کا نام ملکی وے (آکاش گنگا) ہے اور اس میں اربوں ستارے ہیں۔'], ['What is the name of our galaxy?', 'ہماری کہکشاں کا نام کیا ہے؟'], ['The Milky Way', 'ملکی وے (آکاش گنگا)'], [['The Big Dipper', 'بگ ڈِپر'], ['The Sun', 'سورج']]],
            ['gravity', [9, 10], '⬇️', ['Gravity', 'کششِ ثقل'], ['Gravity is a force that pulls things towards each other. It keeps our feet on the ground and keeps the Moon going around the Earth.', 'کششِ ثقل ایک قوت ہے جو چیزوں کو ایک دوسرے کی طرف کھینچتی ہے۔ یہ ہمارے پاؤں زمین پر رکھتی ہے اور چاند کو زمین کے گرد گھماتی ہے۔'], ['What force keeps our feet on the ground?', 'کون سی قوت ہمارے پاؤں زمین پر رکھتی ہے؟'], ['Gravity', 'کششِ ثقل'], [['Wind', 'ہوا'], ['Light', 'روشنی']]],
