            ['dissolve', [6, 8], '🥄', ['Dissolving', 'گھلنا'], ['Sugar dissolves in water: it mixes in and seems to disappear. Sand does not dissolve, it sinks to the bottom.', 'چینی پانی میں گھل جاتی ہے: وہ مل جاتی ہے اور غائب لگتی ہے۔ ریت نہیں گھلتی، وہ نیچے بیٹھ جاتی ہے۔'], ['Which one dissolves in water?', 'پانی میں کون سی چیز گھل جاتی ہے؟'], ['Sugar', 'چینی'], [['Sand', 'ریت'], ['A stone', 'پتھر']]],
            ['water_cycle', [6, 8], '🌧️', ['The water cycle', 'پانی کا چکر'], ['The Sun warms water in the sea and rivers. It rises as invisible vapour, cools into clouds, and falls again as rain.', 'سورج سمندر اور دریاؤں کے پانی کو گرم کرتا ہے۔ وہ نظر نہ آنے والی بھاپ بن کر اوپر جاتا ہے، ٹھنڈا ہو کر بادل بنتا ہے اور پھر بارش بن کر گرتا ہے۔'], ['What warms the water so it can rise and make clouds?', 'پانی کو کون گرم کرتا ہے کہ وہ اوپر جا کر بادل بنائے؟'], ['The Sun', 'سورج'], [['The Moon', 'چاند'], ['The wind', 'ہوا']]],
