            ['what_is_ai', [6, 8], '🧠', ['What is AI?', 'اے آئی کیا ہے؟'], ['AI means artificial intelligence. It is a computer program that learns from lots of examples, so it can do smart jobs like recognising pictures or understanding speech.', 'اے آئی کا مطلب مصنوعی ذہانت ہے۔ یہ ایک کمپیوٹر پروگرام ہے جو بہت سی مثالوں سے سیکھتا ہے، تاکہ تصویریں پہچاننے یا بات سمجھنے جیسے ذہین کام کر سکے۔'], ['What can AI do after it learns from many examples?', 'بہت سی مثالوں سے سیکھنے کے بعد اے آئی کیا کر سکتا ہے؟'], ['Smart jobs, like recognising pictures', 'ذہین کام، جیسے تصویریں پہچاننا'], [['Eat and grow', 'کھانا اور بڑھنا'], ['Feel happy and sad', 'خوش اور اداس ہونا']]],
            ['ai_not_alive', [6, 8], '💡', ['AI is a tool', 'اے آئی ایک اوزار ہے'], ['AI is a tool, like a calculator. It finds patterns in lots of information. It does not have feelings or a body, and it is not alive.', 'اے آئی ایک اوزار ہے، کیلکولیٹر کی طرح۔ وہ بہت سی معلومات میں پیٹرن ڈھونڈتا ہے۔ اس کے جذبات یا جسم نہیں ہوتا اور وہ زندہ نہیں ہے۔'], ['Does AI have feelings like a person?', 'کیا اے آئی کے انسان کی طرح جذبات ہوتے ہیں؟'], ['No, it is a tool', 'نہیں، وہ ایک اوزار ہے'], [['Yes, it gets lonely', 'ہاں، وہ اکیلا محسوس کرتا ہے'], ['Yes, it gets hungry', 'ہاں، اسے بھوک لگتی ہے']]],
            ['ai_health', [6, 8], '🩺', ['AI and doctors', 'اے آئی اور ڈاکٹر'], ['Doctors can use AI to help look at X-ray pictures and spot problems early. The computer only helps: the doctor always makes the final decision about your health.', 'ڈاکٹر ایکس رے کی تصویریں دیکھنے اور مسائل جلدی پہچاننے میں اے آئی سے مدد لے سکتے ہیں۔ کمپیوٹر صرف مدد کرتا ہے: آپ کی صحت کا آخری فیصلہ ہمیشہ ڈاکٹر کرتا ہے۔'], ['Who makes the final decision about your health?', 'آپ کی صحت کے بارے میں آخری فیصلہ کون کرتا ہے؟'], ['The doctor', 'ڈاکٹر'], [['The computer alone', 'اکیلا کمپیوٹر'], ['Nobody', 'کوئی نہیں']]],
            ['ai_study', [6, 8], '📚', ['AI and learning', 'اے آئی اور پڑھائی'], ['AI can help you learn: it can explain a hard word, help translate between languages, or make practice questions. Always check what it says with a teacher or a book, because AI can be wrong.', 'اے آئی پڑھائی میں مدد کر سکتا ہے: وہ مشکل لفظ سمجھا سکتا ہے، زبانوں کا ترجمہ کر سکتا ہے یا مشق کے سوال بنا سکتا ہے۔ اس کی بات ہمیشہ استاد یا کتاب سے جانچ لیں، کیونکہ اے آئی غلط بھی ہو سکتا ہے۔'], ['What should you do after AI helps with your homework?', 'اے آئی ہوم ورک میں مدد کرے تو اس کے بعد کیا کرنا چاہیے؟'], ['Check it with a teacher or a book', 'استاد یا کتاب سے جانچنا'], [['Copy it without reading', 'بغیر پڑھے نقل کر لینا'], ['Never learn it', 'اسے کبھی نہ سیکھنا']]],
            ['ai_translate', [6, 8], '🌐', ['AI and languages', 'اے آئی اور زبانیں'], ['AI can translate between languages like Urdu and English, so people who speak different languages can understand each other.', 'اے آئی اردو اور انگریزی جیسی زبانوں کا ترجمہ کر سکتا ہے، تاکہ مختلف زبانیں بولنے والے لوگ ایک دوسرے کو سمجھ سکیں۔'], ['AI can help translate between...', 'اے آئی کس کے درمیان ترجمہ کرنے میں مدد کر سکتا ہے؟'], ['Languages, like Urdu and English', 'زبانوں کے، جیسے اردو اور انگریزی'], [['Colours', 'رنگوں کے'], ['Planets', 'سیاروں کے']]],
            ['ai_safe', [6, 10], '🔒', ['Using AI safely', 'اے آئی کو محفوظ طریقے سے استعمال کرنا'], ['AI chatbots can make mistakes. Never tell a chatbot your full name, address, school or phone number, or send it photos of yourself. If anything feels strange or scary, tell a grown-up you trust.', 'اے آئی چیٹ بوٹ غلطیاں کر سکتے ہیں۔ چیٹ بوٹ کو کبھی اپنا پورا نام، پتہ، اسکول یا فون نمبر نہ بتائیں اور اپنی تصویریں نہ بھیجیں۔ اگر کوئی بات عجیب یا ڈراؤنی لگے تو کسی بھروسے مند بڑے کو بتائیں۔'], ['What should you never share with a chatbot?', 'چیٹ بوٹ کے ساتھ کیا کبھی شیئر نہیں کرنا چاہیے؟'], ['Your address and private details', 'اپنا پتہ اور ذاتی تفصیلات'], [['Your favourite colour', 'اپنا پسندیدہ رنگ'], ['A joke', 'ایک لطیفہ']]],
            ['ai_hospital', [9, 10], '🏥', ['AI in hospitals', 'ہسپتالوں میں اے آئی'], ['AI can help doctors read scans faster, help scientists find new medicines, and help a smart watch warn about a very fast heartbeat. Doctors and nurses stay in charge.', 'اے آئی ڈاکٹروں کو اسکین جلد پڑھنے، سائنسدانوں کو نئی دوائیں ڈھونڈنے اور اسمارٹ واچ کو بہت تیز دھڑکن سے خبردار کرنے میں مدد دے سکتا ہے۔ ڈاکٹر اور نرسیں ہی ذمہ دار رہتے ہیں۔'], ['How can AI help in a hospital?', 'اے آئی ہسپتال میں کیسے مدد کر سکتا ہے؟'], ['It helps doctors spot problems in pictures', 'وہ ڈاکٹروں کو تصویروں میں مسائل پہچاننے میں مدد دیتا ہے'], [['It replaces all the doctors', 'وہ سب ڈاکٹروں کی جگہ لے لیتا ہے'], ['It cooks the food', 'وہ کھانا پکاتا ہے']]],
            ['ai_farming', [9, 10], '🌾', ['AI on the farm', 'کھیت میں اے آئی'], ['Farmers use cameras, drones and AI to see which plants are thirsty or sick, so they can give water and care only where it is needed.', 'کسان کیمروں، ڈرونز اور اے آئی سے دیکھتے ہیں کہ کون سے پودے پیاسے یا بیمار ہیں، تاکہ پانی اور دیکھ بھال صرف وہیں دیں جہاں ضرورت ہو۔'], ['How can AI help a farmer?', 'اے آئی کسان کی کیسے مدد کر سکتا ہے؟'], ['It spots plants that need water', 'وہ پانی کی ضرورت والے پودے پہچانتا ہے'], [['It makes it rain at once', 'وہ فوراً بارش کروا دیتا ہے'], ['It plants trees by magic', 'وہ جادو سے درخت لگاتا ہے']]],
            ['ai_weather', [9, 10], '🌦️', ['AI and the weather', 'اے آئی اور موسم'], ['Computers and AI study lots of weather information to help predict storms and floods earlier, so people can get ready and stay safe.', 'کمپیوٹر اور اے آئی موسم کی بہت سی معلومات دیکھ کر طوفان اور سیلاب کا پہلے اندازہ لگانے میں مدد دیتے ہیں تاکہ لوگ تیار ہو سکیں اور محفوظ رہیں۔'], ['How can AI help with the weather?', 'اے آئی موسم میں کیسے مدد کر سکتا ہے؟'], ['It helps predict storms earlier', 'وہ طوفانوں کا پہلے اندازہ لگانے میں مدد کرتا ہے'], [['It stops the rain', 'وہ بارش روک دیتا ہے'], ['It makes the Sun brighter', 'وہ سورج کو زیادہ روشن کر دیتا ہے']]],
            ['ai_learns', [9, 10], '📈', ['How AI learns', 'اے آئی کیسے سیکھتا ہے'], ['AI learns from examples. If you show it thousands of pictures of cats and dogs, with the right names, it learns to tell them apart. If the examples are unfair or wrong, the AI can be unfair or wrong too.', 'اے آئی مثالوں سے سیکھتا ہے۔ اگر اسے صحیح ناموں کے ساتھ بلیوں اور کتوں کی ہزاروں تصویریں دکھائیں تو وہ انہیں پہچاننا سیکھ لیتا ہے۔ اگر مثالیں غیر منصفانہ یا غلط ہوں تو اے آئی بھی غیر منصفانہ یا غلط ہو سکتا ہے۔'], ['What does AI learn from?', 'اے آئی کس سے سیکھتا ہے؟'], ['Lots of examples', 'بہت سی مثالوں سے'], [['Sleeping', 'سونے سے'], ['Eating', 'کھانے سے']]],
